    // ---- JSON, shared by the recorder and the bridge (generated by fast-anything)
    static final class Json {
        static final class Unsupported extends RuntimeException {
            Unsupported(String m) { super(m, null, false, false); }
        }

        static String enc(Object v) {
            StringBuilder b = new StringBuilder();
            enc(v, b);
            return b.toString();
        }

        static void enc(Object v, StringBuilder b) {
            if (v == null) b.append("null");
            else if (v instanceof Boolean || v instanceof Integer || v instanceof Long || v instanceof Short || v instanceof Byte) b.append(v);
            else if (v instanceof Double || v instanceof Float) {
                double d = ((Number) v).doubleValue();
                if (!Double.isFinite(d)) throw new Unsupported("NaN or Infinity");
                b.append(v);
            } else if (v instanceof String s) str(s, b);
            else if (v.getClass().isArray()) {
                b.append('[');
                for (int i = 0, n = java.lang.reflect.Array.getLength(v); i < n; i++) {
                    if (i > 0) b.append(',');
                    enc(java.lang.reflect.Array.get(v, i), b);
                }
                b.append(']');
            } else if (v instanceof java.util.List<?> l) {
                b.append('[');
                boolean first = true;
                for (Object x : l) {
                    if (!first) b.append(',');
                    first = false;
                    enc(x, b);
                }
                b.append(']');
            } else if (v instanceof java.util.Map<?, ?> m) {
                b.append('{');
                boolean first = true;
                for (var e : m.entrySet()) {
                    if (!(e.getKey() instanceof String k)) throw new Unsupported("Map with non-String keys");
                    if (!first) b.append(',');
                    first = false;
                    str(k, b);
                    b.append(':');
                    enc(e.getValue(), b);
                }
                b.append('}');
            } else throw new Unsupported(v.getClass().getSimpleName());
        }

        static void str(String s, StringBuilder b) {
            b.append('"');
            for (int i = 0; i < s.length(); i++) {
                char c = s.charAt(i);
                if (Character.isHighSurrogate(c) && i + 1 < s.length() && Character.isLowSurrogate(s.charAt(i + 1))) {
                    b.append(c).append(s.charAt(++i));
                    continue;
                }
                if (Character.isSurrogate(c)) throw new Unsupported("String with a lone surrogate");
                switch (c) {
                    case '"' -> b.append("\\\"");
                    case '\\' -> b.append("\\\\");
                    case '\n' -> b.append("\\n");
                    case '\r' -> b.append("\\r");
                    case '\t' -> b.append("\\t");
                    default -> { if (c < 0x20) b.append(String.format("\\u%04x", (int) c)); else b.append(c); }
                }
            }
            b.append('"');
        }

        static String str(String s) {
            StringBuilder b = new StringBuilder();
            str(s, b);
            return b.toString();
        }

        static Object parse(String s) {
            int[] i = {0};
            return value(s, i);
        }

        static void ws(String s, int[] i) {
            while (i[0] < s.length() && Character.isWhitespace(s.charAt(i[0]))) i[0]++;
        }

        static Object value(String s, int[] i) {
            ws(s, i);
            char c = s.charAt(i[0]);
            if (c == '{') {
                java.util.Map<String, Object> m = new java.util.LinkedHashMap<>();
                i[0]++;
                ws(s, i);
                if (s.charAt(i[0]) == '}') { i[0]++; return m; }
                while (true) {
                    ws(s, i);
                    String k = (String) value(s, i);
                    ws(s, i);
                    i[0]++; // :
                    m.put(k, value(s, i));
                    ws(s, i);
                    if (s.charAt(i[0]++) == '}') return m;
                }
            }
            if (c == '[') {
                java.util.List<Object> l = new java.util.ArrayList<>();
                i[0]++;
                ws(s, i);
                if (s.charAt(i[0]) == ']') { i[0]++; return l; }
                while (true) {
                    l.add(value(s, i));
                    ws(s, i);
                    if (s.charAt(i[0]++) == ']') return l;
                }
            }
            if (c == '"') {
                StringBuilder b = new StringBuilder();
                i[0]++;
                while (true) {
                    char d = s.charAt(i[0]++);
                    if (d == '"') return b.toString();
                    if (d != '\\') { b.append(d); continue; }
                    char e = s.charAt(i[0]++);
                    switch (e) {
                        case 'n' -> b.append('\n');
                        case 'r' -> b.append('\r');
                        case 't' -> b.append('\t');
                        case 'b' -> b.append('\b');
                        case 'f' -> b.append('\f');
                        case 'u' -> { b.append((char) Integer.parseInt(s.substring(i[0], i[0] + 4), 16)); i[0] += 4; }
                        default -> b.append(e);
                    }
                }
            }
            if (s.startsWith("true", i[0])) { i[0] += 4; return Boolean.TRUE; }
            if (s.startsWith("false", i[0])) { i[0] += 5; return Boolean.FALSE; }
            if (s.startsWith("null", i[0])) { i[0] += 4; return null; }
            int start = i[0];
            while (i[0] < s.length() && "+-0123456789.eE".indexOf(s.charAt(i[0])) >= 0) i[0]++;
            String num = s.substring(start, i[0]);
            if (num.contains(".") || num.contains("e") || num.contains("E")) return Double.parseDouble(num);
            try { return Long.parseLong(num); } catch (NumberFormatException ex) { return Double.parseDouble(num); }
        }

        /** A parsed JSON value as the Java type t (from the original method's signature). */
        static Object convert(Object v, java.lang.reflect.Type t) {
            if (v == null) return null;
            if (t instanceof Class<?> c) {
                if (c == int.class || c == Integer.class) return ((Number) v).intValue();
                if (c == long.class || c == Long.class) return ((Number) v).longValue();
                if (c == double.class || c == Double.class) return ((Number) v).doubleValue();
                if (c == float.class || c == Float.class) return ((Number) v).floatValue();
                if (c == short.class || c == Short.class) return ((Number) v).shortValue();
                if (c == byte.class || c == Byte.class) return ((Number) v).byteValue();
                if (c.isArray()) {
                    java.util.List<?> l = (java.util.List<?>) v;
                    Object a = java.lang.reflect.Array.newInstance(c.getComponentType(), l.size());
                    for (int i = 0; i < l.size(); i++) java.lang.reflect.Array.set(a, i, convert(l.get(i), c.getComponentType()));
                    return a;
                }
                if (c == java.util.TreeMap.class) return new java.util.TreeMap<>((java.util.Map<?, ?>) v);
                if (c == java.util.HashMap.class) return new java.util.HashMap<>((java.util.Map<?, ?>) v);
                if (c == java.util.LinkedList.class) return new java.util.LinkedList<>((java.util.List<?>) v);
                return v;
            }
            if (t instanceof java.lang.reflect.ParameterizedType p) {
                Class<?> raw = (Class<?>) p.getRawType();
                java.lang.reflect.Type[] a = p.getActualTypeArguments();
                if (java.util.Map.class.isAssignableFrom(raw)) {
                    java.util.Map<String, Object> m = raw == java.util.TreeMap.class ? new java.util.TreeMap<>()
                        : raw == java.util.HashMap.class ? new java.util.HashMap<>() : new java.util.LinkedHashMap<>();
                    for (var e : ((java.util.Map<?, ?>) v).entrySet()) m.put((String) e.getKey(), convert(e.getValue(), a[1]));
                    return m;
                }
                java.util.List<Object> l = raw == java.util.LinkedList.class ? new java.util.LinkedList<>() : new java.util.ArrayList<>();
                for (Object x : (java.util.List<?>) v) l.add(convert(x, a[0]));
                return l;
            }
            return v;
        }
    }
